# Build the output
output = []
for r in range(6):
    row_output = []
    for c in range(6):
        top, bottom = r*2, (r+1)*2
        left, right = c*2, (c+1)*2
        block = [row[left:right] for row in test_input[top:bottom]]

        # Find the dominant non-0, non-5 color
        colors = set()
        for blk in block:
            for val in blk:
                if val not in (0, 5):
                    colors.add(val)

        if colors:
            row_output.append(list(colors)[0])
        else:
            row_output.append(0)
    output.append(row_output)

print("Output grid (6x6):")
for row in output:
    print(row)
